INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('15cf9089-55c4-4464-895e-f0bee562c7cc', '21feff02-016d-46e2-bb9d-c27495133b1b', '121. óra: Kördiagram', 'Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "6bff183a-fa05-4231-aafc-6963092fc18f", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "371cda7a-9a94-49f3-a93e-a294d3e41095", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "05a92489-27a6-463a-ae36-13ffc09403cf", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "b499aef6-615f-48ab-a5b3-769905d4bea2", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "9704f779-6cdc-4b62-a93f-f8749cb2745a", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "ab2b57f9-610e-4add-938c-68d74e46083d", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "c1329521-41dd-4cc6-a54e-15d8a17894ae", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "5b73b04c-1b38-4949-a8dc-d23e89fd46da", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "1973478f-437b-4e93-933b-5efea8cf69e5", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "ec656b5b-076d-47c3-b415-64e305de149c", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "104c2bb6-b9c9-4c6a-8f9c-155a7141ae91", "text": "Igaz", "isCorrect": true}, {"id": "b49382ba-00a4-488d-a224-c7168a6067fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "17f99c4c-458a-44dc-a2f5-aea62b47bb56", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "39b75d21-287a-41da-a4f3-72ec3886e429", "text": "Igaz", "isCorrect": true}, {"id": "7ab49287-2ff3-4473-8a9d-ccbb3c5d1a0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b5ddf5ba-8dfa-434c-9515-32687944b66e', '21feff02-016d-46e2-bb9d-c27495133b1b', '122. óra: Adatok ábrázolása, átlag', 'Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "efe4564b-1fdd-45e3-ae85-41b08bc72852", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "959cbeed-158d-4372-92f8-95dc0d079a46", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "7d022d57-e928-44e9-9b56-ee2353978091", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "02e2df0f-ba31-419a-8ce6-7095edc358c1", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "2bdd860c-efcc-424c-b5d9-4ae913fa94a4", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "1a489c81-5099-40fb-931a-75f82ce7eb45", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "dc824137-3b59-430e-b18c-401db8b06ec3", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "ed920973-1ce6-4bf6-8c09-91e31d325c66", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "0d5643e2-4614-409f-a6f9-6a355ef690d2", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "dd774295-19ea-4e33-b019-9580bf76903d", "text": "Igaz", "isCorrect": true}, {"id": "54e2fc3c-9f02-4cc5-8a94-a5f60a6bf3c4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "64d4fe59-5eb0-48cc-aa66-bb922223a486", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "ce507777-5a41-430a-9dea-337e975dc739", "text": "Igaz", "isCorrect": true}, {"id": "6d36bf00-7559-4883-bc97-32633e10cd7c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03ede395-b2e0-4f0e-9483-0d1d11a5bcbd", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('be0eae8b-3c5c-4452-bc6f-aee5b21e4798', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "1ad4cd2b-fe7e-4334-9e8c-aa86ac3508c0", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "1125e7a1-cf0a-4012-a9ad-8de2d63146de", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "a8cd9be6-6b24-4f15-8984-361694355b3f", "text": "1 a 2-ből", "isCorrect": false}, {"id": "c28928d8-f5c1-4497-89a6-fab342b6b0e9", "text": "100%", "isCorrect": false}, {"id": "7b5a0111-7a04-4607-ad8d-4c2a30d0eaa3", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "be32254c-3b8a-45d0-aa44-077ef62fdecf", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "3fb7b919-a87c-45e4-9d94-dccf49ad311e", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "ee8ec385-2067-4f2f-8855-37cdc110d2ec", "text": "1/6", "isCorrect": false}, {"id": "f10bbf84-8860-4717-bd28-774e9a93b352", "text": "2/6", "isCorrect": false}, {"id": "ce0a553b-96ad-4a0e-adce-f71617e506e5", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "e4ec778c-141a-4bf2-8c4e-d71184b02e47", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "41a65fae-43e9-445f-b409-5ce41c0513ae", "text": "Igaz", "isCorrect": true}, {"id": "68c9b89a-5f26-4280-8eb3-325b5ff66f73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4e28fc87-5867-42e2-a216-8ccf43460d7e", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "98f33972-cffb-4d26-91bd-3e1502a52adf", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "f0742d0b-8720-4498-be35-8a97c7d6500e", "text": "Biztos esemény", "isCorrect": false}, {"id": "b6e17345-7e76-46e8-803b-4c2dbd756360", "text": "Lehetséges", "isCorrect": false}, {"id": "db4b2c62-3925-433d-ba66-b47207e9b1a5", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "9a91297c-959a-42dd-8d8e-81d8d4bd4522", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "8dcf34c5-d468-4446-9315-7821439a499c", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "dd45be01-01d0-4a16-988b-8f931433808f", "text": "Lehetetlen", "isCorrect": false}, {"id": "d94dd7f3-cabd-4dfa-8fca-3830277bfe14", "text": "Kétes", "isCorrect": false}, {"id": "70c3997b-eef4-45a5-897c-6fe42d5490d3", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "b6e8eaad-8967-4df7-b9d8-eb4ed62f7be9", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "be6f785f-0499-4320-bb1e-2d7158201c8b", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "a57ec41d-073d-4267-a778-417f200fd612", "text": "Igaz", "isCorrect": true}, {"id": "6c9fb842-d98f-40c6-a1c4-6d29634a86ea", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('47b8a2d1-2472-4635-bc18-dae54e5f3f8c', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "37c96c66-8ed1-4e14-88e2-60fffd0978bc", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "b5bc5ecb-dc9b-49dd-88c6-d9c37f53347d", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "751c4dc3-8d06-4ab3-831c-43a1c0ebd15f", "text": "1/4", "isCorrect": false}, {"id": "055a1436-c259-47fc-88a4-4d633203516a", "text": "100%", "isCorrect": false}, {"id": "8a0cf4fa-ca1f-4a69-af6d-ee9cc299bd3c", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "fb52fe74-61b6-4ada-ace3-d35c9630412b", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "a5c256f1-6818-48db-aa73-6d47148b928f", "text": "Igaz", "isCorrect": true}, {"id": "03fd29e4-132b-4ac0-a4e0-5f16de0d7579", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8854ad4-ac87-4738-a21b-a8fdc8445222", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "71cac398-7062-4b32-8092-62ae2cb91156", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "97134bd1-b25b-4299-8114-cb781d7ba206", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "f7f4e375-aa7d-4b1a-908d-9e046ca764a8", "text": "Igaz", "isCorrect": true}, {"id": "01a46cee-4032-499d-a2ce-1f813acbfe14", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c6e3271c-b417-4df7-95c3-dce54358e20b", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "bb6d7867-77be-4a10-a108-8cf4a3d8604e", "text": "Igaz", "isCorrect": true}, {"id": "384d8177-2682-4956-aae0-62f8fdb646bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "57d88617-ae0f-4484-8afc-56a7f2202267", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "e22ba33e-6a88-475c-9bfd-524ac5cdaf63", "text": "Igaz", "isCorrect": true}, {"id": "e5b993d8-207d-4bd0-a333-b709baf5b507", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d9c8a1c8-7bef-4505-9f70-d83dc3b72a96', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "31318bec-6b70-441b-b6fd-80ce018a31e0", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "4e08a4af-ca1a-492c-b482-bdb6bbd6d7f2", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "687cb41c-6597-4ab6-9de6-03c9d0a044f5", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "cc199751-d954-4f53-abcf-9dcb0b7626c3", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "8c51d620-6dc5-46bd-81dc-ff489bc56d78", "text": "Igaz", "isCorrect": true}, {"id": "5fe51448-6b96-4547-a401-f7d2e8e56656", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f33a20e4-5ff0-4557-afb2-2bbedc1a1f4e", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "c8923e55-1a08-473e-89ff-ef49055c9461", "text": "Igaz", "isCorrect": true}, {"id": "0ac96d36-25ec-4f94-bf86-b7abe1240e0c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6cda5902-571f-4277-aaf6-d5c0a05a3170", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "fc469925-9bdd-43d3-b9e4-ab52b0e1de3c", "text": "Vonaldiagram", "isCorrect": true}, {"id": "02c9f4b9-876f-4fe0-9552-31ea9aafc84a", "text": "Kördiagram", "isCorrect": false}, {"id": "4a8b7a90-4321-4bf4-ac4d-4ce3e07a3930", "text": "Pontdiagram", "isCorrect": false}, {"id": "7ab78d20-ea8c-4c66-977e-01d9c53e9d38", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "56eca12d-cfdb-432c-b9b4-9123355ab638", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('245b937f-64b7-41f2-a60f-3aaddac25903', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "97fcf197-3963-4348-82ba-acdd77d50eb7", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "3a869c52-9569-4061-8b0f-bdfae5909c06", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "e7678e0f-3f43-4ff7-aa53-a7ac0516558c", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "463d1754-7dac-4083-824e-f07b02503ece", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "315bf6a8-b2f2-4093-8066-189c7652dc3a", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "3c3c7a57-8aec-41eb-9013-b6dbc57ea693", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "51cbe89a-2d69-4d7e-8356-6f649f10ce3e", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "feacea82-c6d4-40ab-9d9e-b55d87cc4b39", "text": "Biztos esemény", "isCorrect": false}, {"id": "01391b6a-6769-412e-bde4-0e3e46a673b3", "text": "Lehetséges", "isCorrect": false}, {"id": "97c65075-d650-4c13-bd0b-fd51ec98e74a", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "e1cbf377-fbd5-484d-814a-a578dd487db9", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "5dd88d0f-1822-4fe9-9832-37692eabad2e", "text": "Biztos esemény", "isCorrect": true}, {"id": "a720d042-e246-4397-bee8-7507e5d5546d", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "82317a2b-33c6-48ca-b71b-e6cc6552d7da", "text": "Ritka", "isCorrect": false}, {"id": "65097664-0f48-4eb3-b8a0-bd9eb4e2f741", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72a0cd0e-d328-4bbb-bf73-4f2a7ed77e1b", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "cf87401d-bafa-4bb1-811e-14bae16a2771", "text": "Igaz", "isCorrect": true}, {"id": "9c6cefdf-9ad5-49b3-8eca-a594a9fc526c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f5029c77-a856-4eea-891e-734533de19b8", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "f47a6f19-ab48-46e4-a601-4686205579ef", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "85d6692f-8283-4c99-922b-56923a44a035", "text": "Igaz", "isCorrect": true}, {"id": "347dcb37-9eaa-4b74-a54e-8b02bd99443c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('db42392e-71b0-4327-8b9a-a4dd2e112033', '21feff02-016d-46e2-bb9d-c27495133b1b', '127. óra: A számonkérés értékelése', 'A statisztikai feladatok és projektmunkák megbeszélése, értékelése.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "823c1cbe-1e2a-4859-91c6-5b0eeaf8a6d0", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "98d73931-adc6-465a-941a-e258fce3b0cd", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "ac1df054-febe-49d9-905e-3edb6e6092d1", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "1853fbf8-24dc-42f8-b837-bb1e6cc3e014", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "2b03c3ab-ffde-4410-ae5b-c98382486441", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "16e46c66-ba09-4b37-a3fe-813d71df01b7", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "40c81180-9307-46a8-90a6-7010b6ad553a", "text": "Igaz", "isCorrect": true}, {"id": "b4bd6dbd-0fd6-43aa-9f0c-97903332fd63", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bbe5b502-3f13-4126-a2ff-fc7d323d0445", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "3e146ccd-ca20-4303-aa68-90d549ec4042", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "8232e5e2-4244-440a-a7b8-772f1edfd63b", "text": "Igaz", "isCorrect": true}, {"id": "2d77de93-b57d-4554-8331-6f01ff74adf1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2ed333a-6929-4ba1-84d0-4b50eb220349", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "4ac9f6f3-a608-4343-b1ce-f1692593c2e6", "text": "Igaz", "isCorrect": true}, {"id": "33ed81b5-bbc2-4a12-964d-251791c8d420", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2cc7b240-6435-472b-b2b7-542c4d1130d1", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "cbf17cc1-a779-4d87-b4bf-28a5eb40ea5b", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "d8bd6d49-e601-47b4-9204-60200d9975dd", "text": "Igaz", "isCorrect": true}, {"id": "b1df7005-ff44-49c7-954b-8e644bfea7e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f734a562-8b4f-4ad7-bab3-8b3055d442b4', '21feff02-016d-46e2-bb9d-c27495133b1b', '128. óra: Mindennapi pénzügyeink I.', 'Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "d2c14a32-693b-4455-ad67-42888cc12079", "text": "Mit jelent a banki megtakarítás (betét) után járó ''kamat''?", "type": "multiple-choice", "options": [{"id": "ad02b6b0-bc47-485d-9cf0-bf2d33bf0ef1", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "4f0f6231-cbfc-431c-834f-0459006177f5", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "9c09905b-6d28-41b4-ac45-5ceb8f1a78cd", "text": "A büntetés", "isCorrect": false}, {"id": "cf088e82-3027-463c-92a4-f8e4cea89352", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "d31af63d-444e-4464-8f80-490c869040c1", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "562e8ce4-9b97-4109-b748-f572b2101c2d", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "42ae54e8-657b-4ae5-8a07-e93717b5bad0", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "8bf06490-8b15-447b-98a1-fa311253ec3b", "text": "Igaz", "isCorrect": true}, {"id": "86bc97cf-02af-4866-af30-774c38d46542", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c60a0af-9b30-401d-9c2a-3d1562de6f96", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "3a63ce50-6c4f-46a6-a104-b6524aa667f5", "text": "Igaz", "isCorrect": true}, {"id": "ad8016d4-992a-478e-afc4-3b61a4dbb355", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "313188bb-13a3-4806-97d9-758d3322a8ae", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "d6c96ac2-a562-4669-b8b6-e93e4a42e6a7", "text": "Igaz", "isCorrect": true}, {"id": "0e27e5fa-957f-4bb7-9e38-3b8dab27986f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2069c0b3-f675-4b48-ba1d-ec239ec3d73c", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5e9122b8-3742-4ad2-84b3-99f50e8a96f8', '21feff02-016d-46e2-bb9d-c27495133b1b', '129. óra: Mindennapi pénzügyeink II.', 'Devizák, valutavételi és -eladási árfolyam, valutaváltás.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "3c84d719-91cf-4bc0-8b7f-1820eaea9f69", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "c5195de5-7ce7-4063-aa6e-1bb492731345", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "b89cfd7e-f961-4dbe-bbaa-626bf420f584", "text": "A bankjegy színe", "isCorrect": false}, {"id": "e8234d69-1b3e-480e-b6a1-6e4576501cef", "text": "A pénz súlya", "isCorrect": false}, {"id": "9b1ff207-c769-41c3-a260-0ff3675f8603", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "96e6bcfe-be28-4cfb-9bbf-41274476c979", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "1913dc45-5a67-4fd2-bf2a-aafc44a79dbd", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "41d7fd91-fb2a-4539-bc21-3215c1704c46", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "f2ab86ab-b549-4997-80b8-725c23280e7e", "text": "Igaz", "isCorrect": true}, {"id": "58b70694-5bd9-4004-b285-59fdf35925c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0d59646e-d0ed-483b-ab96-3243ac662201", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "24a2a289-fa23-4b5f-a5ef-0b0a4f52a0a6", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "2430478b-d5fe-4300-a641-d04e0e5beab6", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "f18bede6-02f0-4221-8e85-a08b00a7f9c6", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "3be7b9ca-5d1e-4fca-b962-6c3605ec2c06", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "3bcc8eba-482b-4e10-a98a-6fdc538b2124", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "e3116eea-1fab-47a3-bcec-84b951d2567e", "text": "Igaz", "isCorrect": true}, {"id": "e727c2ef-6218-47d5-8b01-c9d93b1af1e3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "205c6d0f-ecb7-49e0-93a8-1d64457f4e88", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6836285f-5c4f-487b-b4f3-d4d9a6acc5a3', '21feff02-016d-46e2-bb9d-c27495133b1b', '130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "693b06a7-273b-4d13-bb54-4c9187105c01", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c2d1a7df-6911-4265-a794-5b5a9bc9404b", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "ae0ab158-0a3a-4bf8-bc26-4965788f6b31", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "2c3c6b68-2aaf-4709-ada3-0d61dc1fec66", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "3763dfc9-456f-427e-9890-97832564e04b", "text": "Igaz", "isCorrect": true}, {"id": "075c3de6-566b-457a-92d4-27e303cdb794", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "49129bbb-76d1-4c2b-bc2f-5a250d196073", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "b72018c1-cf82-4b6b-b6fe-4546748d7bf0", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "70e3994e-7546-4031-8ce9-703bca44ba52", "text": "-4", "isCorrect": true}, {"id": "af81ff0f-0ad5-46d2-81f8-ac1e641a6d12", "text": "-12", "isCorrect": false}, {"id": "bd3872e1-be3c-4c52-bbfd-044a8157a64c", "text": "Egyenlők", "isCorrect": false}, {"id": "ef9e8fb8-354e-4ac7-9cf1-d35e0ed30ec2", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "e725a1d3-83f2-4e1d-9a9b-76e74dbebba6", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;